WITH valid AS (SELECT id, session_id, event_type, event_time, duration_sec, LOWER(page) AS page_lower, COALESCE(page, 'N/A') AS resolved_page FROM web_events WHERE duration_sec <= 327), gaps AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time, id) > INTERVAL 90 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM valid), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY event_type ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT DATE_TRUNC('MONTH', event_time) AS activity_month, session_no, MAX(event_time) AS last_seen, ROUND(SUM(new_group_flag) / NULLIF(COUNT(CASE WHEN event_type = 'purchase' THEN 1 END), 0), 2) AS new_group_flag_per_purchase, SIZE(COLLECT_SET(event_type)) AS num_event_types, MAX(event_time) AS last_event_time, MIN(event_time) AS first_seen FROM sessionized GROUP BY ROLLUP (DATE_TRUNC('MONTH', event_time), session_no) HAVING new_group_flag_per_purchase > 0
